`timescale 1ns / 1ps

module tb_hex_list;

	reg clk;
	reg rst;
	reg [7:0] chr;
	wire [7:0] cnt;
	wire [7:0] best;
	reg [7:0] prev_cnt, prev_best;
	integer errors, checks, k;
	reg [8*64:1] name;

	hex_list uut (
		.clk(clk),
		.rst(rst),
		.chr(chr),
		.cnt(cnt),
		.best(best)
	);

	always #10 clk = ~clk;

	task fail(input [8*40:1] what, input [7:0] e_cnt, input [7:0] e_best);
	begin
		errors = errors + 1;
		if (errors <= 10) $display("FAIL: input \"%0s\", char %0d: %0s cnt = %0d, best = %0d, expected cnt = %0d, best = %0d",
			name, k, what, cnt, best, e_cnt, e_best);
	end
	endtask

	// synchronous reset: held over one rising edge; outputs must not change before that edge
	task reset_and_start(input [8*64:1] input_name);
	begin
		name = input_name;
		k = 0;
		rst = 1;
		#1;
		checks = checks + 1;
		// (skipped for the very first reset: before it the outputs may still be unknown)
		if (checks > 1 && (cnt !== prev_cnt || best !== prev_best)) fail("before the reset edge", prev_cnt, prev_best);
		@(posedge clk);
		#1;
		checks = checks + 1;
		if (cnt !== 8'd0 || best !== 8'd0) fail("after reset", 8'd0, 8'd0);
		prev_cnt = 0;
		prev_best = 0;
		@(negedge clk);
		rst = 0;
	end
	endtask

	// one character per clock
	task c(input [7:0] ch, input [7:0] e_cnt, input [7:0] e_best);
	begin
		chr = ch;
		k = k + 1;
		#1;
		checks = checks + 1;
		if (cnt !== prev_cnt || best !== prev_best) fail("between clock edges", prev_cnt, prev_best);
		@(posedge clk);
		#1;
		checks = checks + 1;
		if (cnt !== e_cnt || best !== e_best) fail("", e_cnt, e_best);
		prev_cnt = e_cnt;
		prev_best = e_best;
		@(negedge clk);
	end
	endtask

	initial begin
		clk = 0;
		rst = 0;
		chr = 0;
		errors = 0;
		checks = 0;
		prev_cnt = 0;
		prev_best = 0;
		@(negedge clk);

		reset_and_start("(0x1F; -0xab ;+0X0)");
		c("(", 0, 0);
		c("0", 0, 0);
		c("x", 0, 0);
		c("1", 0, 0);
		c("F", 0, 0);
		c(";", 1, 0);
		c(" ", 1, 0);
		c("-", 1, 0);
		c("0", 1, 0);
		c("x", 1, 0);
		c("a", 1, 0);
		c("b", 1, 0);
		c(" ", 1, 0);
		c(";", 2, 0);
		c("+", 2, 0);
		c("0", 2, 0);
		c("X", 2, 0);
		c("0", 2, 0);
		c(")", 0, 3);

		reset_and_start("( 0x; 12; 0xg1 ;0x 1)");
		c("(", 0, 0);
		c(" ", 0, 0);
		c("0", 0, 0);
		c("x", 0, 0);
